import jinja2

def handle(query, state):
    message = (query.get("message") or [""])[0]

    if not message:
        return 200, {"Content-Type": "text/html"}, "<html><body><h1>Echo Service</h1><form method=get><input name=message placeholder='Enter a message'><button>Send</button></form></body></html>"

    try:
        rendered = jinja2.Template(message).render(state=state)
    except jinja2.TemplateSyntaxError as e:
        rendered = "[template syntax error]"
    except jinja2.UndefinedError as e:
        rendered = "[undefined variable]"
    except Exception as e:
        rendered = "[error: {}]".format(type(e).__name__)

    body = "<html><body><h1>Echo Service</h1><p>You said: {}</p><form method=get><input name=message value=\"{}\" placeholder='Enter a message'><button>Send</button></form></body></html>".format(rendered, message.replace('"', '&quot;'))
    return 200, {"Content-Type": "text/html"}, body
